import { Controller, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 멘션 알림의 채널은 포털, 이벤트 유형은 멘션으로 고정한다.
const MENTION_CHANNEL = '포털';
const MENTION_EVENT_TYPE = '멘션';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isDigits(value: unknown): boolean {
  return /^\d+$/.test(String(value ?? ''));
}

@Controller('api/v1')
export class FnSfr02801Controller {
  @Get('/notifications')
  async listNotifications(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const rawSize = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(rawSize) || rawSize < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '한 쪽 건수가 올바르지 않습니다.');
    }
    const size = Math.min(rawSize, MAX_SIZE);
    const readStatus = q['readStatus'] ? String(q['readStatus']) : null;
    if (readStatus !== null && readStatus !== '안읽음' && readStatus !== '읽음') {
      throw new ApiError(400, 'VALIDATION_FAILED', '읽음 상태는 안읽음 또는 읽음이어야 합니다.');
    }
    const eventType = q['eventType'] ? String(q['eventType']) : null;
    return transaction(async (db) => {
      const params = {
        userId: user.id,
        readStatus,
        eventType,
        size,
        offset: page * size,
      };
      const where = `recipient_id = CAST(:userId AS bigint)
        AND (CAST(:readStatus AS varchar) IS NULL OR read_status = CAST(:readStatus AS varchar))
        AND (CAST(:eventType AS varchar) IS NULL OR event_type = CAST(:eventType AS varchar))`;
      const items = await db.query(
        `SELECT notification_id AS "notificationId",
          channel AS "channel",
          title AS "title",
          content AS "content",
          read_status AS "readStatus",
          event_type AS "eventType",
          target_type AS "targetType",
          target_id AS "targetId",
          created_at AS "createdAt"
        FROM notification
        WHERE ${where}
        ORDER BY created_at DESC, notification_id DESC
        LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        params,
      );
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM notification WHERE ${where}`,
        { userId: user.id, readStatus, eventType },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/notifications/mentions')
  @HttpCode(200)
  async createMentionNotifications(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    if (!isDigits(data['recipientId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수신자를 선택해 주세요.');
    }
    const title = typeof data['title'] === 'string' ? data['title'].trim() : '';
    if (title === '' || title.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 제목은 1자 이상 200자 이하로 입력해 주세요.');
    }
    if (data['content'] !== undefined && data['content'] !== null && typeof data['content'] !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 내용 형식이 올바르지 않습니다.');
    }
    const targetType = typeof data['targetType'] === 'string' ? data['targetType'].trim() : '';
    if (targetType === '' || targetType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '바로가기 대상 유형을 입력해 주세요.');
    }
    if (!isDigits(data['targetId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '바로가기 대상 ID는 숫자로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:recipientId AS bigint)',
        { recipientId: String(data['recipientId']) },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'MENTION_RECIPIENT_NOT_FOUND', '멘션 대상 사용자를 찾을 수 없습니다.');
      }
      // TODO(질문): 멘션 대상 사용자의 콘텐츠 접근 권한 확인 기준이 없어 MENTION_ACCESS_DENIED(422)는 구현하지 못했다.
      const rows = await db.query(
        `INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
        VALUES (CAST(:recipientId AS bigint), :channel, :title, :content, '안읽음', :eventType, :targetType, CAST(:targetId AS bigint), now(), now())
        RETURNING notification_id AS "notificationId"`,
        {
          recipientId: String(data['recipientId']),
          channel: MENTION_CHANNEL,
          title,
          content: data['content'] ?? null,
          eventType: MENTION_EVENT_TYPE,
          targetType,
          targetId: String(data['targetId']),
        },
      );
      return { notificationId: Number(rows[0]['notificationId']) };
    });
  }

  @Patch('/notifications/:notificationId/read')
  async readNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = req.params['notificationId'];
    if (!isDigits(notificationId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT read_status AS "readStatus" FROM notification
        WHERE notification_id = CAST(:notificationId AS bigint)
          AND recipient_id = CAST(:userId AS bigint)`,
        { notificationId, userId: user.id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '본인에게 발송된 알림을 찾을 수 없습니다.');
      }
      if (found[0]['readStatus'] !== '안읽음') {
        throw new ApiError(409, 'INVALID_STATE', '이미 읽은 알림입니다.');
      }
      const rows = await db.query(
        `UPDATE notification
        SET read_status = '읽음', read_at = now(), updated_at = now()
        WHERE notification_id = CAST(:notificationId AS bigint)
          AND recipient_id = CAST(:userId AS bigint)
          AND read_status = '안읽음'
        RETURNING notification_id AS "notificationId", read_status AS "readStatus", read_at AS "readAt"`,
        { notificationId, userId: user.id },
      );
      return rows[0];
    });
  }
}

