import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  NumberInput,
  Pager,
  Pairs,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr02801Page({ role, notify }: PageProps) {
  const [readStatus, setReadStatus] = useState('');
  const [eventType, setEventType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [recipientId, setRecipientId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/notifications', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  function search() {
    setPage(0);
    setApplied({ readStatus, eventType });
  }

  function reset() {
    setReadStatus('');
    setEventType('');
    setPage(0);
    setApplied({});
  }

  function openCreate() {
    setRecipientId('');
    setTitle('');
    setContent('');
    setTargetType('');
    setTargetId('');
    setCreating(true);
  }

  async function submitMention() {
    if (recipientId === '' || title.trim() === '' || targetType.trim() === '' || targetId === '') {
      throw new Error('수신자, 알림 제목, 바로가기 대상 유형, 바로가기 대상 ID를 모두 입력해 주세요.');
    }
    await call('POST', '/notifications/mentions', role, {
      recipientId,
      title,
      content,
      targetType,
      targetId,
    });
    notify('멘션 알림을 보냈습니다.');
    setCreating(false);
    reload();
  }

  async function markRead() {
    if (!selected) return;
    await call('PATCH', '/notifications/' + String(selected['notificationId']) + '/read', role, {});
    notify('알림을 읽음으로 처리했습니다.');
    setSelected(null);
    reload();
  }

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>알림 내용</h2>
          <Pairs
            items={[
              ['알림 제목', String(selected['title'] ?? '')],
              ['알림 내용', String(selected['content'] ?? '')],
              ['알림 채널', String(selected['channel'] ?? '')],
              ['알림 이벤트 유형', String(selected['eventType'] ?? '')],
              ['읽음 상태', <Badge value={selected['readStatus']} />],
              ['생성 일시', <DateText value={selected['createdAt']} time />],
            ]}
          />
        </section>
        <section className="box">
          <h2>바로가기 대상</h2>
          <Pairs
            items={[
              ['바로가기 대상 유형', String(selected['targetType'] ?? '')],
              ['바로가기 대상 ID', String(selected['targetId'] ?? '')],
            ]}
          />
        </section>
        {selected['readStatus'] === '안읽음' && (
          <Form onSubmit={markRead} submit="읽음으로 처리">
            <p>이 알림을 읽음 상태로 바꿉니다.</p>
          </Form>
        )}
      </div>
    );
  }

  return (
    <div className="doc">
      <h2>알림과 멘션</h2>
      <Filters onSearch={search} onReset={reset}>
        <Field label="읽음 상태">
          <Select
            value={readStatus}
            onChange={setReadStatus}
            options={[
              ['안읽음', '안읽음'],
              ['읽음', '읽음'],
            ]}
            placeholder="전체"
          />
        </Field>
        <Field label="알림 이벤트 유형">
          <TextInput value={eventType} onChange={setEventType} />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openCreate}>멘션 알림 보내기</button>
      </Band>
      {error && <p>{error}</p>}
      {loading && <p>불러오는 중입니다.</p>}
      <DataTable
        columns={[
          { key: 'title', label: '알림 제목' },
          { key: 'eventType', label: '알림 이벤트 유형' },
          { key: 'channel', label: '알림 채널' },
          { key: 'readStatus', label: '읽음 상태', render: (r) => <Badge value={r['readStatus']} /> },
          { key: 'createdAt', label: '생성 일시', render: (r) => <DateText value={r['createdAt']} time /> },
        ]}
        rows={data?.items ?? []}
        onRowClick={(r) => setSelected(r)}
        empty="받은 알림이 아직 없습니다."
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      {creating && (
        <Drawer title="멘션 알림 보내기" onClose={() => setCreating(false)}>
          <Form onSubmit={submitMention} submit="보내기">
            <Field label="수신자" required>
              <LookupSelect table="employee" role={role} value={recipientId} onChange={setRecipientId} />
            </Field>
            <Field label="알림 제목" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="알림 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="바로가기 대상 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="바로가기 대상 ID" required>
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
